window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-ccb5cfe30565ed79"]={"versions": [{"id": "FIG-ccb5cfe30565ed79", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Funktionales Schichten- und Allokationsdiagramm (<em>Functional Architecture / Use Case Allocation Diagram</em>) mit Schnittstellen-Mapping für die AUTOSAR Classic Platform (CP, R20-11/R21-11; dokumentiert in <code>AUTOSAR_EXP_AIADASAndVMC</code>).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der vertikalen Signal- und Steuerungsarchitektur für das Anwendungsfallszenario <em>Adaptive Cruise Control</em> (ACC, reine Längsführung). Es demonstriert das Skalierungsprinzip des 4-Ebenen-Referenzmodells durch gezielte Aktivierung längsdynamischer Schnittstellen (<code>Used I/F</code>) bei gleichzeitiger Deaktivierung querdynamischer Schnittstellen und Funktionsblöcke (<code>Not used I/F</code>, <code>Not used function</code>).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Architekturschichten &amp; Software-Komponenten (SWCs)</h5>\n<ul class=\"fig-list\"><li><strong><code>[3.1.1] ADAS Application</code>:</strong> Oberste Applikationsebene.\n<ul class=\"fig-list\"><li><em>Entität:</em> <code>ACC</code> (aktiv / <em>Used function</em>); berechnet Soll-Abstands- und Geschwindigkeitsvorgaben auf Basis von Fahrerwunsch und Umfelddaten.\n</li></ul>\n</li><li><strong><code>[3.1.2] ADAS-MGR (AMG)</code>:</strong> <em>ADAS Manager</em> (aktiv).\n<ul class=\"fig-list\"><li>Verantwortlich für funktionale Arbitrierung, Betriebsmodi-Umschaltung und Validierung der Assistenzfunktions-Anforderungen auf Subsystem-Ebene.\n</li></ul>\n</li><li><strong><code>[3.1.3] Vehicle-MGR (VMG)</code>:</strong> <em>Vehicle Motion Manager</em> (aktiv).\n<ul class=\"fig-list\"><li>Zentrale Instanz für die Koordination der Fahrzeugbewegung (<em>Vehicle Motion Control</em>); übersetzt übergeordnete Bewegungswünsche in konkrete Stellbefehle für Antrieb und Bremse.\n</li></ul>\n</li><li><strong><code>[3.1.4] Actuator</code>:</strong> Aktuator- und Basis-Sensorik-Ebene.\n<ul class=\"fig-list\"><li><code>Powertrain</code> (aktiv / <em>Used function</em>): Antriebsstrangsteuerung (Inverter/Motor/Getriebe).\n</li><li><code>Brake</code> (aktiv / <em>Used function</em>): Reibbremssystem / ESP / Bremselektronik.\n</li><li><code>Steering</code> (inaktiv / <em>Not used function</em>, ausgegraut): Lenksystem / EPS; im reinen ACC-Betrieb nicht angesteuert.\n</li><li><code>Sensors</code> (aktiv / <em>Used function</em>): Fahrzustandssensorik (z. B. Raddrehzahlen, Gierrate, Längsbeschleunigung).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen (AUTOSAR Ports / Interfaces)</h5>\n<ul class=\"fig-list\"><li><strong>Zwischen <code>ADAS Application</code> und <code>ADAS-MGR</code>:</strong>\n<ul class=\"fig-list\"><li><code>PLN1</code> (<em>Downlink, aktiv</em>): <em>Planning Demand Interface</em> – Übertragung der Soll-Trajektorie bzw. Längsbeschleunigungsanforderung vom ACC an den AMG.\n</li><li><code>PLN2</code> (<em>Uplink, aktiv</em>): <em>Planning Feedback Interface</em> – Rückmeldung von Status, Systemgrenzen und Verfügbarkeiten vom AMG an das ACC.\n</li></ul>\n</li><li><strong>Zwischen <code>ADAS-MGR</code> und <code>Vehicle-MGR</code>:</strong>\n<ul class=\"fig-list\"><li><code>VMC1</code> (<em>Downlink, aktiv</em>): <em>Vehicle Motion Control Demand Interface</em> – Aggregierte Sollbeschleunigung / Sollkraft von AMG an VMG.\n</li><li><code>VMC2</code> (<em>Uplink, aktiv</em>): <em>Vehicle Motion Control Feedback Interface</em> – Aggregierte fahrdynamische Grenzwerte, aktuelle Bewegungsistwerte und Aktor-Bereitschaften von VMG an AMG.\n</li></ul>\n</li><li><strong>Zwischen <code>Vehicle-MGR</code> und <code>Actuator</code>:</strong>\n<ul class=\"fig-list\"><li><code>ACL1</code> (<em>Downlink, aktiv</em>): <em>Acceleration Control Interface</em> – Stellgröße für Antriebsmoment/Beschleunigung an <code>Powertrain</code>.\n</li><li><code>BRK1</code> (<em>Downlink, aktiv</em>): <em>Brake Control Interface</em> – Stellgröße für Verzögerung/Bremsmoment an <code>Brake</code>.\n</li><li><code>STR1</code> (<em>Downlink, inaktiv</em>): <em>Steering Control Interface</em> – Lenkwinkel-/Lenkmomentanforderung an <code>Steering</code> (ungesteuert).\n</li><li><code>ACL2</code> (<em>Uplink, aktiv</em>): <em>Acceleration Feedback Interface</em> – Istreaktion, Antriebsstatus und Drehmomentgrenzen von <code>Powertrain</code>.\n</li><li><code>BRK2</code> (<em>Uplink, aktiv</em>): <em>Brake Feedback Interface</em> – Bremsdruck, Bremsstatus und ABS/ESP-Eingriffe von <code>Brake</code>.\n</li><li><code>STR2</code> (<em>Uplink, inaktiv</em>): <em>Steering Feedback Interface</em> – Lenkwinkel-/Ritzelmoment-Rückmeldung (inaktiv).\n</li><li><code>VSS2</code> (<em>Uplink, aktiv</em>): <em>Vehicle Sensor System Interface</em> – Roh-/Vorverarbeitete Fahrzeugzustandsgrößen (Fahrzeuggeschwindigkeit, Raddrehzahlen) von <code>Sensors</code> an VMG.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Zustandserfassung (Uplink, zyklisch):</strong>\n<ul class=\"fig-list\"><li><code>Sensors</code> liefert Geschwindigkeits- und Odometriedaten über <code>VSS2</code> an den <code>VMG</code>.\n</li><li><code>Powertrain</code> und <code>Brake</code> melden ihren aktuellen Status, Realisierungsgrenzen und Eingriffsstati über <code>ACL2</code> bzw. <code>BRK2</code> an den <code>VMG</code>.\n</li><li><code>VMG</code> bündelt und filtert die fahrdynamischen Zustände und übermittelt den Fahrzeugzustand via <code>VMC2</code> an den <code>AMG</code>.\n</li><li><code>AMG</code> spiegelt Ausführungsstatus und Systemlimits via <code>PLN2</code> an die Applikations-SWC <code>ACC</code>.\n</li></ul>\n</li><li><strong>Sollwertberechnung &amp; Kaskadierung (Downlink, synchron/zyklisch):</strong>\n<ul class=\"fig-list\"><li>Die <code>ACC</code>-SWC berechnet anhand der Sensorziele und Regelabweichung eine Ziel-Längsbeschleunigung (a_x,target) und sendet diese über <code>PLN1</code> an den <code>AMG</code>.\n</li><li><code>AMG</code> prüft die Anforderung gegen Sicherheitsgrenzen und reicht die freigegebene Längsführungsanforderung über <code>VMC1</code> an den <code>VMG</code> weiter.\n</li></ul>\n</li><li><strong>Aktuator-Arbitrierung &amp; Split (VMG):</strong>\n<ul class=\"fig-list\"><li><code>VMG</code> führt die Momenten-/Beschleunigungsarbitrierung durch:\n<ul class=\"fig-list\"><li>Bei positiver oder neutraler Beschleunigungsanforderung (a_x ≥ a_drag): Ansteuerung von <code>Powertrain</code> via <code>ACL1</code>.\n</li><li>Bei Verzögerungsanforderung (a_x &lt; a_drag): Koordination von Nutzbremse (<code>Powertrain</code>, Rekuperation) und Reibbremse (<code>Brake</code> via <code>BRK1</code>).\n</li></ul>\n</li><li>Der Pfad <code>STR1</code> bleibt im VMG passiviert (kein Lenkeingriff generiert).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>VFB- &amp; RTE-Generierung (Port Mapping):</strong>\n<ul class=\"fig-list\"><li>Nicht genutzte Ports (<code>STR1</code>, <code>STR2</code>) dürfen im RTE-Contract- und Component-Design als unverbunden deklariert oder per AUTOSAR <em>Variant Handling</em> (<code>VariationPoint</code>) deaktiviert werden, um RAM/ROM-Puffer im RTE-Routing und PDU-Last auf dem Bus (CAN-FD/FlexRay/Ethernet) einzusparen.\n</li></ul>\n</li><li><strong>Interface-Standardisierung:</strong>\n<ul class=\"fig-list\"><li>Die Schnittstellen <code>PLN1/2</code>, <code>VMC1/2</code> sowie <code>ACL/BRK/STR/VSS</code> folgen dem AUTOSAR-Standard <em>Application Interfaces for ADAS and VMC</em>. Die Port-Interfaces sind typischerweise als <em>Sender-Receiver-Interfaces</em> mit zyklischer Abtastung (z. B. 10 ms oder 20 ms Task-Raster) definiert.\n</li></ul>\n</li><li><strong>Sicherheits- &amp; Degradationspfad (ISO 26262):</strong>\n<ul class=\"fig-list\"><li>Fällt ein Uplink aus (<code>ACL2</code>, <code>BRK2</code>, <code>VSS2</code>), muss der <code>VMG</code> diesen Fehler über <code>VMC2</code> an den <code>AMG</code> eskalieren. Der <code>AMG</code> erzwingt die Deaktivierung oder den geordneten Übergang des <code>ACC</code> in den passiven Zustand (Rückfallebene/Safe State).\n</li></ul>\n</li></ul>"}, {"id": "FIG-0d2b07d384033597", "releases": ["R22-11", "R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Funktionales Schichten- und Allokationsdiagramm (<em>Functional Architecture / Use Case Allocation Diagram</em>) mit Schnittstellen-Mapping für die AUTOSAR Classic Platform (CP, R20-11/R21-11; dokumentiert in <code>AUTOSAR_EXP_AIADASAndVMC</code>).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der vertikalen Signal- und Steuerungsarchitektur für das Anwendungsfallszenario <em>Adaptive Cruise Control</em> (ACC, reine Längsführung). Es demonstriert das Skalierungsprinzip des 4-Ebenen-Referenzmodells durch gezielte Aktivierung längsdynamischer Schnittstellen (<code>Used I/F</code>) bei gleichzeitiger Deaktivierung querdynamischer Schnittstellen und Funktionsblöcke (<code>Not used I/F</code>, <code>Not used function</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Architekturschichten &amp; Software-Komponenten (SWCs)</h5>\n<ul class=\"fig-list\"><li><strong><code>[4.1.1] ADAS Application</code>:</strong> Oberste Applikationsebene.\n<ul class=\"fig-list\"><li><em>Entität:</em> <code>ACC</code> (aktiv / <em>Used function</em>); berechnet Soll-Abstands- und Geschwindigkeitsvorgaben auf Basis von Fahrerwunsch und Umfelddaten.\n</li></ul>\n</li><li><strong><code>[4.1.2] ADAS-MGR (AMG)</code>:</strong> <em>ADAS Manager</em> (aktiv).\n<ul class=\"fig-list\"><li>Verantwortlich für funktionale Arbitrierung, Betriebsmodi-Umschaltung und Validierung der Assistenzfunktions-Anforderungen auf Subsystem-Ebene.\n</li></ul>\n</li><li><strong><code>[4.1.3] Vehicle-MGR (VMG)</code>:</strong> <em>Vehicle Motion Manager</em> (aktiv).\n<ul class=\"fig-list\"><li>Zentrale Instanz für die Koordination der Fahrzeugbewegung (<em>Vehicle Motion Control</em>); übersetzt übergeordnete Bewegungswünsche in konkrete Stellbefehle für Antrieb und Bremse.\n</li></ul>\n</li><li><strong><code>[4.1.4] Actuator</code>:</strong> Aktuator- und Basis-Sensorik-Ebene.\n<ul class=\"fig-list\"><li><code>Powertrain</code> (aktiv / <em>Used function</em>): Antriebsstrangsteuerung (Inverter/Motor/Getriebe).\n</li><li><code>Brake</code> (aktiv / <em>Used function</em>): Reibbremssystem / ESP / Bremselektronik.\n</li><li><code>Steering</code> (inaktiv / <em>Not used function</em>, ausgegraut): Lenksystem / EPS; im reinen ACC-Betrieb nicht angesteuert.\n</li><li><code>Sensors</code> (aktiv / <em>Used function</em>): Fahrzustandssensorik (z. B. Raddrehzahlen, Gierrate, Längsbeschleunigung).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen (AUTOSAR Ports / Interfaces)</h5>\n<ul class=\"fig-list\"><li><strong>Zwischen <code>ADAS Application</code> und <code>ADAS-MGR</code>:</strong>\n<ul class=\"fig-list\"><li><code>PLN1</code> (<em>Downlink, aktiv</em>): <em>Planning Demand Interface</em> – Übertragung der Soll-Trajektorie bzw. Längsbeschleunigungsanforderung vom ACC an den AMG.\n</li><li><code>PLN2</code> (<em>Uplink, aktiv</em>): <em>Planning Feedback Interface</em> – Rückmeldung von Status, Systemgrenzen und Verfügbarkeiten vom AMG an das ACC.\n</li></ul>\n</li><li><strong>Zwischen <code>ADAS-MGR</code> und <code>Vehicle-MGR</code>:</strong>\n<ul class=\"fig-list\"><li><code>VMC1</code> (<em>Downlink, aktiv</em>): <em>Vehicle Motion Control Demand Interface</em> – Aggregierte Sollbeschleunigung / Sollkraft von AMG an VMG.\n</li><li><code>VMC2</code> (<em>Uplink, aktiv</em>): <em>Vehicle Motion Control Feedback Interface</em> – Aggregierte fahrdynamische Grenzwerte, aktuelle Bewegungsistwerte und Aktor-Bereitschaften von VMG an AMG.\n</li></ul>\n</li><li><strong>Zwischen <code>Vehicle-MGR</code> und <code>Actuator</code>:</strong>\n<ul class=\"fig-list\"><li><code>ACL1</code> (<em>Downlink, aktiv</em>): <em>Acceleration Control Interface</em> – Stellgröße für Antriebsmoment/Beschleunigung an <code>Powertrain</code>.\n</li><li><code>BRK1</code> (<em>Downlink, aktiv</em>): <em>Brake Control Interface</em> – Stellgröße für Verzögerung/Bremsmoment an <code>Brake</code>.\n</li><li><code>STR1</code> (<em>Downlink, inaktiv</em>): <em>Steering Control Interface</em> – Lenkwinkel-/Lenkmomentanforderung an <code>Steering</code> (ungesteuert).\n</li><li><code>ACL2</code> (<em>Uplink, aktiv</em>): <em>Acceleration Feedback Interface</em> – Istreaktion, Antriebsstatus und Drehmomentgrenzen von <code>Powertrain</code>.\n</li><li><code>BRK2</code> (<em>Uplink, aktiv</em>): <em>Brake Feedback Interface</em> – Bremsdruck, Bremsstatus und ABS/ESP-Eingriffe von <code>Brake</code>.\n</li><li><code>STR2</code> (<em>Uplink, inaktiv</em>): <em>Steering Feedback Interface</em> – Lenkwinkel-/Ritzelmoment-Rückmeldung (inaktiv).\n</li><li><code>VSS2</code> (<em>Uplink, aktiv</em>): <em>Vehicle Sensor System Interface</em> – Roh-/Vorverarbeitete Fahrzeugzustandsgrößen (Fahrzeuggeschwindigkeit, Raddrehzahlen) von <code>Sensors</code> an VMG.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Zustandserfassung (Uplink, zyklisch):</strong>\n<ul class=\"fig-list\"><li><code>Sensors</code> liefert Geschwindigkeits- und Odometriedaten über <code>VSS2</code> an den <code>VMG</code>.\n</li><li><code>Powertrain</code> und <code>Brake</code> melden ihren aktuellen Status, Realisierungsgrenzen und Eingriffsstati über <code>ACL2</code> bzw. <code>BRK2</code> an den <code>VMG</code>.\n</li><li><code>VMG</code> bündelt und filtert die fahrdynamischen Zustände und übermittelt den Fahrzeugzustand via <code>VMC2</code> an den <code>AMG</code>.\n</li><li><code>AMG</code> spiegelt Ausführungsstatus und Systemlimits via <code>PLN2</code> an die Applikations-SWC <code>ACC</code>.\n</li></ul>\n</li><li><strong>Sollwertberechnung &amp; Kaskadierung (Downlink, synchron/zyklisch):</strong>\n<ul class=\"fig-list\"><li>Die <code>ACC</code>-SWC berechnet anhand der Sensorziele und Regelabweichung eine Ziel-Längsbeschleunigung (a_x,target) und sendet diese über <code>PLN1</code> an den <code>AMG</code>.\n</li><li><code>AMG</code> prüft die Anforderung gegen Sicherheitsgrenzen und reicht die freigegebene Längsführungsanforderung über <code>VMC1</code> an den <code>VMG</code> weiter.\n</li></ul>\n</li><li><strong>Aktuator-Arbitrierung &amp; Split (VMG):</strong>\n<ul class=\"fig-list\"><li><code>VMG</code> führt die Momenten-/Beschleunigungsarbitrierung durch:\n<ul class=\"fig-list\"><li>Bei positiver oder neutraler Beschleunigungsanforderung (a_x ≥ a_drag): Ansteuerung von <code>Powertrain</code> via <code>ACL1</code>.\n</li><li>Bei Verzögerungsanforderung (a_x &lt; a_drag): Koordination von Nutzbremse (<code>Powertrain</code>, Rekuperation) und Reibbremse (<code>Brake</code> via <code>BRK1</code>).\n</li></ul>\n</li><li>Der Pfad <code>STR1</code> bleibt im VMG passiviert (kein Lenkeingriff generiert).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>VFB- &amp; RTE-Generierung (Port Mapping):</strong>\n<ul class=\"fig-list\"><li>Nicht genutzte Ports (<code>STR1</code>, <code>STR2</code>) dürfen im RTE-Contract- und Component-Design als unverbunden deklariert oder per AUTOSAR <em>Variant Handling</em> (<code>VariationPoint</code>) deaktiviert werden, um RAM/ROM-Puffer im RTE-Routing und PDU-Last auf dem Bus (CAN-FD/FlexRay/Ethernet) einzusparen.\n</li></ul>\n</li><li><strong>Interface-Standardisierung:</strong>\n<ul class=\"fig-list\"><li>Die Schnittstellen <code>PLN1/2</code>, <code>VMC1/2</code> sowie <code>ACL/BRK/STR/VSS</code> folgen dem AUTOSAR-Standard <em>Application Interfaces for ADAS and VMC</em>. Die Port-Interfaces sind typischerweise als <em>Sender-Receiver-Interfaces</em> mit zyklischer Abtastung (z. B. 10 ms oder 20 ms Task-Raster) definiert.\n</li></ul>\n</li><li><strong>Sicherheits- &amp; Degradationspfad (ISO 26262):</strong>\n<ul class=\"fig-list\"><li>Fällt ein Uplink aus (<code>ACL2</code>, <code>BRK2</code>, <code>VSS2</code>), muss der <code>VMG</code> diesen Fehler über <code>VMC2</code> an den <code>AMG</code> eskalieren. Der <code>AMG</code> erzwingt die Deaktivierung oder den geordneten Übergang des <code>ACC</code> in den passiven Zustand (Rückfallebene/Safe State).\n</li></ul>\n</li></ul>"}, {"id": "FIG-dd809c073be87ee0", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Funktionales Schichten- und Allokationsdiagramm (<em>Functional Architecture / Use Case Allocation Diagram</em>) mit Schnittstellen-Mapping für die AUTOSAR Classic Platform (CP, R20-11/R21-11; dokumentiert in <code>AUTOSAR_EXP_AIADASAndVMC</code>).\n</li><li><strong>Technischer Zweck:</strong> Spezifikation der vertikalen Signal- und Steuerungsarchitektur für das Anwendungsfallszenario <em>Adaptive Cruise Control</em> (ACC, reine Längsführung). Es demonstriert das Skalierungsprinzip des 4-Ebenen-Referenzmodells durch gezielte Aktivierung längsdynamischer Schnittstellen (<code>Used I/F</code>) bei gleichzeitiger Deaktivierung querdynamischer Schnittstellen und Funktionsblöcke (<code>Not used I/F</code>, <code>Not used function</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Architekturschichten &amp; Software-Komponenten (SWCs)</h5>\n<ul class=\"fig-list\"><li><strong><code>[4.1.1] ADAS Application</code>:</strong> Oberste Applikationsebene.\n<ul class=\"fig-list\"><li><em>Entität:</em> <code>ACC</code> (aktiv / <em>Used function</em>); berechnet Soll-Abstands- und Geschwindigkeitsvorgaben auf Basis von Fahrerwunsch und Umfelddaten.\n</li></ul>\n</li><li><strong><code>[4.1.2] ADAS-MGR (AMG)</code>:</strong> <em>ADAS Manager</em> (aktiv).\n<ul class=\"fig-list\"><li>Verantwortlich für funktionale Arbitrierung, Betriebsmodi-Umschaltung und Validierung der Assistenzfunktions-Anforderungen auf Subsystem-Ebene.\n</li></ul>\n</li><li><strong><code>[4.1.3] Vehicle-MGR (VMG)</code>:</strong> <em>Vehicle Motion Manager</em> (aktiv).\n<ul class=\"fig-list\"><li>Zentrale Instanz für die Koordination der Fahrzeugbewegung (<em>Vehicle Motion Control</em>); übersetzt übergeordnete Bewegungswünsche in konkrete Stellbefehle für Antrieb und Bremse.\n</li></ul>\n</li><li><strong><code>[4.1.4] Actuator</code>:</strong> Aktuator- und Basis-Sensorik-Ebene.\n<ul class=\"fig-list\"><li><code>Powertrain</code> (aktiv / <em>Used function</em>): Antriebsstrangsteuerung (Inverter/Motor/Getriebe).\n</li><li><code>Brake</code> (aktiv / <em>Used function</em>): Reibbremssystem / ESP / Bremselektronik.\n</li><li><code>Steering</code> (inaktiv / <em>Not used function</em>, ausgegraut): Lenksystem / EPS; im reinen ACC-Betrieb nicht angesteuert.\n</li><li><code>Sensors</code> (aktiv / <em>Used function</em>): Fahrzustandssensorik (z. B. Raddrehzahlen, Gierrate, Längsbeschleunigung).\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Schnittstellen (AUTOSAR Ports / Interfaces)</h5>\n<ul class=\"fig-list\"><li><strong>Zwischen <code>ADAS Application</code> und <code>ADAS-MGR</code>:</strong>\n<ul class=\"fig-list\"><li><code>PLN1</code> (<em>Downlink, aktiv</em>): <em>Planning Demand Interface</em> – Übertragung der Soll-Trajektorie bzw. Längsbeschleunigungsanforderung vom ACC an den AMG.\n</li><li><code>PLN2</code> (<em>Uplink, aktiv</em>): <em>Planning Feedback Interface</em> – Rückmeldung von Status, Systemgrenzen und Verfügbarkeiten vom AMG an das ACC.\n</li></ul>\n</li><li><strong>Zwischen <code>ADAS-MGR</code> und <code>Vehicle-MGR</code>:</strong>\n<ul class=\"fig-list\"><li><code>VMC1</code> (<em>Downlink, aktiv</em>): <em>Vehicle Motion Control Demand Interface</em> – Aggregierte Sollbeschleunigung / Sollkraft von AMG an VMG.\n</li><li><code>VMC2</code> (<em>Uplink, aktiv</em>): <em>Vehicle Motion Control Feedback Interface</em> – Aggregierte fahrdynamische Grenzwerte, aktuelle Bewegungsistwerte und Aktor-Bereitschaften von VMG an AMG.\n</li></ul>\n</li><li><strong>Zwischen <code>Vehicle-MGR</code> und <code>Actuator</code>:</strong>\n<ul class=\"fig-list\"><li><code>ACL1</code> (<em>Downlink, aktiv</em>): <em>Acceleration Control Interface</em> – Stellgröße für Antriebsmoment/Beschleunigung an <code>Powertrain</code>.\n</li><li><code>BRK1</code> (<em>Downlink, aktiv</em>): <em>Brake Control Interface</em> – Stellgröße für Verzögerung/Bremsmoment an <code>Brake</code>.\n</li><li><code>STR1</code> (<em>Downlink, inaktiv</em>): <em>Steering Control Interface</em> – Lenkwinkel-/Lenkmomentanforderung an <code>Steering</code> (ungesteuert).\n</li><li><code>ACL2</code> (<em>Uplink, aktiv</em>): <em>Acceleration Feedback Interface</em> – Istreaktion, Antriebsstatus und Drehmomentgrenzen von <code>Powertrain</code>.\n</li><li><code>BRK2</code> (<em>Uplink, aktiv</em>): <em>Brake Feedback Interface</em> – Bremsdruck, Bremsstatus und ABS/ESP-Eingriffe von <code>Brake</code>.\n</li><li><code>STR2</code> (<em>Uplink, inaktiv</em>): <em>Steering Feedback Interface</em> – Lenkwinkel-/Ritzelmoment-Rückmeldung (inaktiv).\n</li><li><code>VSS2</code> (<em>Uplink, aktiv</em>): <em>Vehicle Sensor System Interface</em> – Roh-/Vorverarbeitete Fahrzeugzustandsgrößen (Fahrzeuggeschwindigkeit, Raddrehzahlen) von <code>Sensors</code> an VMG.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Zustandserfassung (Uplink, zyklisch):</strong>\n<ul class=\"fig-list\"><li><code>Sensors</code> liefert Geschwindigkeits- und Odometriedaten über <code>VSS2</code> an den <code>VMG</code>.\n</li><li><code>Powertrain</code> und <code>Brake</code> melden ihren aktuellen Status, Realisierungsgrenzen und Eingriffsstati über <code>ACL2</code> bzw. <code>BRK2</code> an den <code>VMG</code>.\n</li><li><code>VMG</code> bündelt und filtert die fahrdynamischen Zustände und übermittelt den Fahrzeugzustand via <code>VMC2</code> an den <code>AMG</code>.\n</li><li><code>AMG</code> spiegelt Ausführungsstatus und Systemlimits via <code>PLN2</code> an die Applikations-SWC <code>ACC</code>.\n</li></ul>\n</li><li><strong>Sollwertberechnung &amp; Kaskadierung (Downlink, synchron/zyklisch):</strong>\n<ul class=\"fig-list\"><li>Die <code>ACC</code>-SWC berechnet anhand der Sensorziele und Regelabweichung eine Ziel-Längsbeschleunigung (a_x,target) und sendet diese über <code>PLN1</code> an den <code>AMG</code>.\n</li><li><code>AMG</code> prüft die Anforderung gegen Sicherheitsgrenzen und reicht die freigegebene Längsführungsanforderung über <code>VMC1</code> an den <code>VMG</code> weiter.\n</li></ul>\n</li><li><strong>Aktuator-Arbitrierung &amp; Split (VMG):</strong>\n<ul class=\"fig-list\"><li><code>VMG</code> führt die Momenten-/Beschleunigungsarbitrierung durch:\n<ul class=\"fig-list\"><li>Bei positiver oder neutraler Beschleunigungsanforderung (a_x ≥ a_drag): Ansteuerung von <code>Powertrain</code> via <code>ACL1</code>.\n</li><li>Bei Verzögerungsanforderung (a_x &lt; a_drag): Koordination von Nutzbremse (<code>Powertrain</code>, Rekuperation) und Reibbremse (<code>Brake</code> via <code>BRK1</code>).\n</li></ul>\n</li><li>Der Pfad <code>STR1</code> bleibt im VMG passiviert (kein Lenkeingriff generiert).\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>VFB- &amp; RTE-Generierung (Port Mapping):</strong>\n<ul class=\"fig-list\"><li>Nicht genutzte Ports (<code>STR1</code>, <code>STR2</code>) dürfen im RTE-Contract- und Component-Design als unverbunden deklariert oder per AUTOSAR <em>Variant Handling</em> (<code>VariationPoint</code>) deaktiviert werden, um RAM/ROM-Puffer im RTE-Routing und PDU-Last auf dem Bus (CAN-FD/FlexRay/Ethernet) einzusparen.\n</li></ul>\n</li><li><strong>Interface-Standardisierung:</strong>\n<ul class=\"fig-list\"><li>Die Schnittstellen <code>PLN1/2</code>, <code>VMC1/2</code> sowie <code>ACL/BRK/STR/VSS</code> folgen dem AUTOSAR-Standard <em>Application Interfaces for ADAS and VMC</em>. Die Port-Interfaces sind typischerweise als <em>Sender-Receiver-Interfaces</em> mit zyklischer Abtastung (z. B. 10 ms oder 20 ms Task-Raster) definiert.\n</li></ul>\n</li><li><strong>Sicherheits- &amp; Degradationspfad (ISO 26262):</strong>\n<ul class=\"fig-list\"><li>Fällt ein Uplink aus (<code>ACL2</code>, <code>BRK2</code>, <code>VSS2</code>), muss der <code>VMG</code> diesen Fehler über <code>VMC2</code> an den <code>AMG</code> eskalieren. Der <code>AMG</code> erzwingt die Deaktivierung oder den geordneten Übergang des <code>ACC</code> in den passiven Zustand (Rückfallebene/Safe State).\n</li></ul>\n</li></ul>"}], "trans": [{"from": "FIG-ccb5cfe30565ed79", "to": "FIG-0d2b07d384033597", "fr": "R21-11", "tr": "R22-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>[3.1.1] ADAS Application</code>: Blocknummerierung zu <code>[4.1.1] ADAS Application</code> aktualisiert (Anpassung an die geänderte Kapitelnummerierung der Spezifikation).\n</li><li><code>[3.1.2] ADAS-MGR (AMG)</code>: Blocknummerierung zu <code>[4.1.2] ADAS-MGR (AMG)</code> aktualisiert.\n</li><li><code>[3.1.3] Vehicle-MGR (VMG)</code>: Blocknummerierung zu <code>[4.1.3] Vehicle-MGR (VMG)</code> aktualisiert.\n</li><li><code>[3.1.4] Actuator</code>: Blocknummerierung zu <code>[4.1.4] Actuator</code> aktualisiert.\n</li></ul>"}, {"from": "FIG-0d2b07d384033597", "to": "FIG-dd809c073be87ee0", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
